html:
{% set dob = frappe.db.get_value("Patient", doc.patient, "dob") %}
{% set years = 0 %}
{% set months = 0 %}
{% set days = 0 %}
{% if dob %}
    {% set now  = frappe.utils.nowdate() %}
    {% set diff = frappe.utils.date_diff(now, dob) %}
    {% set years = diff//365 %}
    {% set months = (diff - (years * 365))//30 %}
    {% set days = ( (diff - (years * 365)) - (months * 30) ) %}
{% endif %}
{% set age_display = "" %}
{% if years > 0 %}
    {% set age_display = years|str + 'Y' %}
{% else %}
    {% set age_display = months|str + 'M ' + days|str + 'D'  %}
{% endif %}
<div style="font-family: arial, sans-serif;">
    <b><div style="text-align: center; margin-bottom: -2px; font-size:8px;">{{doc.patient_name|upper}}<br>
    {{doc.patient}}, {{age_display}} / {{doc.patient_gender[:1]}}</div>
    <div style="text-align:center;"><img class="barcode" style="width: 350px; height: 50px;" src="data:image/png;base64,{{ generate_barcodes(doc.name) }}"></div>
    <div  style="text-align:center; font-size:8px; margin-top: -8px;">{{doc.name}}</div>
    <div style="text-align: center; font-size:8px;">{{doc.specimen_type|upper}}</div></b>
</div>

css:
/* ===============================
   إعدادات عامة
=============================== */
@page {
  size: A4;
  margin-top: 15mm;
  margin-bottom: 15mm;
  margin-left: 15mm;
  margin-right: 15mm;
}

body {
  font-family: "Cairo", "Tajawal", "Almarai", sans-serif;
  direction: rtl;
  text-align: right;
  font-size: 12px;
  color: #000;
}

/* ===============================
   العناوين
=============================== */
h1, h2, h3, h4 {
  text-align: center;
  font-weight: bold;
  margin-bottom: 10px;
}

.section-head {
  text-align: right;
  font-weight: bold;
  font-size: 14px;
  border-bottom: 1px solid #ccc;
  margin: 15px 0 8px;
  padding-bottom: 4px;
}

/* ===============================
   الحقول والتسميات
=============================== */
.label {
  font-weight: 600;
  text-align: right;
  float: right;
  width: 35%;
  padding-left: 10px;
}

.value {
  text-align: right;
  float: right;
  width: 65%;
}

/* محاذاة التسميات لليمين */
.align-labels-right .label {
  text-align: right;
}

/* ===============================
   الجداول
=============================== */
table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 10px;
}

th, td {
  border: 1px solid #444;
  padding: 6px 8px;
  text-align: right;
  vertical-align: middle;
}

th {
  background-color: #f2f2f2;
  font-weight: bold;
}

/* ===============================
   إظهار فواصل بعد الأقسام
=============================== */
.section {
  margin-bottom: 20px;
  padding-bottom: 10px;
  border-bottom: 1px dashed #bbb;
}

/* ===============================
   الأرقام والقيم
=============================== */
.number,
.currency {
  direction: ltr;
  text-align: right;
}

/* عرض القيم السالبة كموجبة (Visual فقط) */
.absolute-value {
  unicode-bidi: bidi-override;
}

/* ===============================
   رقم الصفحة (إخفاء)
=============================== */
.page-number,
.pagenum,
.footer {
  display: none !important;
}

/* ===============================
   تحسين الطباعة
=============================== */
.no-print {
  display: none !important;
}

.clearfix::after {
  content: "";
  display: block;
  clear: both;
}

.print-format th {
    background-color: transparent !important;
    border-bottom: 1px solid !important;
    border-top: none !important;
}
.print-format .ql-editor {
    padding-left: 0px;
    padding-right: 0px;
}

.print-format table {
    margin-bottom: 0px;
    }
.print-format .table-data tr:last-child { 
    border-bottom: 1px solid !important;
}

.print-format .table-inner tr:last-child {
    border-bottom:none !important;
}
.print-format .table-inner {
    margin: 0px 0px;
}

.print-format .table-data ul li { 
    color:#787878 !important;
}

.no-top-border {
    border-top:none !important;
}

.table-inner td {
    padding-left: 0px !important;    
    padding-top: 1px !important;
    padding-bottom: 1px !important;
    color:#787878 !important;
}

.total {
    background-color: lightgrey !important;
    padding-top: 4px !important;
    padding-bottom: 4px !important;
}

