css:
/* ========================== CSS ========================== */
@page { size: A4; margin: 15mm 15mm; }

.print-format {
    font-family: "Sultan Regular","Tahoma",Arial,sans-serif;
    direction: rtl;
    text-align: right;
    font-size: 12px;
    line-height: 1.5;
    color: #000;
    background: #fff;
}

/* رأس التقرير */
.report-header {
    text-align: center;
    margin-bottom: 15px;
    padding: 10px 0;
    border-bottom: 2px solid #333;
    background-color: #f5f5f5;
    border-radius: 8px;
}
.report-header .title {
    font-family: "Sultan Bold","Tahoma";
    font-size: 22px;
    font-weight: bold;
    color: #000;
    margin-bottom: 4px;
}
.report-header .sub-title {
    font-size: 14px;
    color: #555;
}

/* العناوين الفرعية */
.print-format h2, .print-format h3 {
    font-family: "Sultan Bold","Tahoma";
    font-weight: bold;
    color: #000;
    page-break-after: avoid;
}
.print-format h2 {
    font-size: 16px;
    margin: 18px 0 10px;
    padding: 8px 10px;
    background: #eef2f5;
    border-right: 4px solid #2c3e50;
    border-radius: 4px;
}
.print-format h3 {
    font-size: 13px;
    margin: 12px 0 6px;
    padding-right: 6px;
    border-right: 3px solid #3498db;
}

/* الأقسام */
.section-container { 
    page-break-inside: avoid; 
    margin-bottom: 12px;
}

/* صناديق المعلومات */
.info-box {
    margin-bottom: 12px;
    padding: 10px;
    background: #fff;
    border: 1px solid #ccc;
    border-radius: 6px;
}
.info-box span {
    display: inline-block;
    min-width: 130px;
    font-weight: bold;
    color: #222;
}

/* الجداول */
.print-format table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 12px;
    background-color: #fff;
    table-layout: fixed;
}
.print-format th {
    background: #f0f0f0;
    border: 1px solid #999;
    padding: 6px 4px;
    text-align: center;
    font-size: 12px;
    font-weight: bold;
    color: #000;
    vertical-align: middle;
}
.print-format td {
    border: 1px solid #bbb;
    padding: 5px 6px;
    vertical-align: top;
    word-wrap: break-word;
    overflow-wrap: break-word;
    font-size: 11.5px;
}
thead { display: table-header-group; }
tr { page-break-inside: avoid; }

/* Child Tables Headers */
.print-format table tbody tr:nth-child(odd) {
    background-color: #fcfcfc;
}
.print-format table tbody tr:nth-child(even) {
    background-color: #f9f9f9;
}

/* التوصيات والملاحظات */
.print-format .recommendations {
    margin-top: 8px;
    padding: 10px;
    background: #fbfbfb;
    border: 1px solid #ddd;
    border-right: 3px solid #27ae60;
    border-radius: 5px;
}
.print-format .recommendations ol, 
.print-format .recommendations ul,
.print-format ol,
.print-format ul {
    padding-right: 20px !important;
    padding-left: 0 !important;
    margin-right: 0;
    text-align: right;
    direction: rtl;
}
.print-format .recommendations li,
.print-format li {
    margin-bottom: 4px;
    line-height: 1.6;
}

/* تحسين عرض الحقول الكبيرة */
.print-format td span, .print-format td div {
    display: block;
    word-wrap: break-word;
}

/* فواصل الأعمدة (Column Break) */
.column-break {
    display: inline-block;
    width: 10px;
}

/* أحجام الخط للحقول الأساسية */
.print-format .info-box, .print-format td, .print-format th {
    font-size: 12px;
}

/* ========================= جداول فيما يخص الوقف ========================= */
.print-format .waqf-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 15px;
    table-layout: fixed;
}
.print-format .waqf-table th {
    background-color: #dce6f1;
    border: 1px solid #999;
    padding: 6px 4px;
    text-align: center;
}
.print-format .waqf-table td {
    border: 1px solid #bbb;
    padding: 5px 6px;
    text-align: center;
}

/* ========================= جداول فيما يخص القرآنية ========================= */
.print-format .quranic-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 15px;
    table-layout: fixed;
}
.print-format .quranic-table th {
    background-color: #f7e6d7;
    border: 1px solid #999;
    padding: 6px 4px;
    text-align: center;
}
.print-format .quranic-table td {
    border: 1px solid #bbb;
    padding: 5px 6px;
    text-align: center;
}

/* صفوف متناوبة للجداول الجديدة */
.print-format .waqf-table tbody tr:nth-child(odd),
.print-format .quranic-table tbody tr:nth-child(odd) {
    background-color: #fcfcfc;
}
.print-format .waqf-table tbody tr:nth-child(even),
.print-format .quranic-table tbody tr:nth-child(even) {
    background-color: #f9f9f9;
}
